function systemAppearanceChanged(event:MediaQueryListEvent):void{systemLight.value=event.matches}
systemAppearance.addEventListener('change',systemAppearanceChanged)
const music=useMusic(),page=ref('home'),playlistId=ref('default'),source=ref<SourceId|'all'>('wy'),keyword=ref(''),searchResult=ref<SearchResult>(),online=ref<OnlinePlaylist[]>([]),boards=ref<{id:string;name:string}[]>([]),boardId=ref(''),onlineDetail=ref<{info:OnlinePlaylist;tracks:Track[]}>(),busy=ref(false),pageNumber=ref(1),discoveryTab=ref('playlists'),drawer=ref(false),fullLyrics=ref(false),comments=ref<Comment[]>([]),commentTrack=ref<Track>(),commentPage=ref(1),suggestions=ref<string[]>([]),hot=ref<string[]>([]),lyricContainer=ref<HTMLElement>(),dialog=ref<'create'|'rename'|'remove'|'collect'|'transfer'|''>(''),dialogName=ref(''),pendingTracks=ref<Track[]>([]),dialogInput=ref<HTMLInputElement>(),desktopMode=new URLSearchParams(location.search).get('lyric')==='1',desktopStatus=ref<PlayerStatus>(),desktopLocked=ref(false),desktopTop=ref(true),filter=ref(''),searchFocused=ref(false),searchBox=ref<HTMLElement>()
const playlist=computed(()=>music.library.playlists.find(p=>p.id===playlistId.value)),allTracks=computed(()=>{const map=new Map<string,Track>();for(const p of music.library.playlists)for(const t of p.tracks)map.set(trackKey(t),t);return [...map.values()]}),filteredTracks=computed(()=>{const tracks=page.value==='search'?searchResult.value?.list||[]:page.value==='online'?onlineDetail.value?.tracks||[]:playlist.value?.tracks||[];return filter.value?tracks.filter(t=>`${t.name} ${t.singer} ${t.meta.albumName}`.toLowerCase().includes(filter.value.toLowerCase())):tracks}),activeScripts=computed(()=>music.library.scripts.filter(s=>s.enabled)),availableSources=computed(()=>Object.keys(sourceNames).filter(s=>s!=='local') as SourceId[]),theme=computed(()=>music.settings.theme==='system'?(systemLight.value?'light':'dark'):music.settings.theme)
const sortField=ref('name'),sortDirection=ref('asc')
const onlineImportTarget=ref('')
const alternativesTrack=ref<Track>()
const onlineTarget=ref<OnlineTarget>(),detailTrack=ref<Track>(),detailLoading=ref(false),transferMove=ref(false),playlistDrag=ref(-1)
const playerCollectOnly=ref(false),customPlaylists=computed(()=>music.library.playlists.filter(list=>!['default','love'].includes(list.id)))
watch(dialog,value=>{if(!value)playerCollectOnly.value=false})
const activeAppearance=computed(()=>{
 const id=theme.value==='light'?music.settings.themeLightId:music.settings.themeDarkId
 const collection=music.settings.userThemes as Record<string,import('./domain/theme').ThemeFile>|undefined
 return music.settings.theme==='system'&&typeof id==='string'?collection?.[id]:undefined
})
const componentAppearance=computed(()=>normalizeAppearance(music.settings.appearance))
watch(()=>music.settings.appearance,value=>applyAppearance(value),{immediate:true,deep:true})
