const backgroundStyle=computed(()=>{const value=activeAppearance.value?.background??music.settings.themeBackground;return validThemeBackground(value)&&value?{backgroundImage:`url(${JSON.stringify(value)})`,opacity:Math.max(0,Math.min(1,Number(activeAppearance.value?.backgroundOpacity??music.settings.themeBackgroundOpacity??.25)))}:undefined})
function externalLink(url:unknown):url is string{return typeof url==='string'&&url.length<=2048&&/^https?:\/\//i.test(url)}
async function openExternal(url:string):Promise<void>{if(externalLink(url))await music.task(()=>invoke('app.openExternal',{url}))}
const sourceURL = ref('')
async function importSourceURL(): Promise<void> {
  await music.task(async () => {
    const result = await invoke('sources.importURL', { url: sourceURL.value.trim() })
    if (result) { sourceURL.value = ''; music.notify('音源脚本已导入') }
  })
}
watch(() => music.settings.language, language => { document.documentElement.lang=normalizeInterfaceLanguage(language); void interfaceTranslation?.setLanguage(language) }, { immediate:true })
const interfaceText=(text:string)=>t(text,music.settings.language)
watch(page,(value,previous)=>{searchFocused.value=false;if(previous!=='search'||value==='search')return;if(music.settings.clearSearchInput)keyword.value='';if(music.settings.clearSearchResults){clearSearchSession();searchResult.value=undefined;suggestions.value=[]}})
const navigation=[['home','House','为你推荐'],['discovery','Compass','发现音乐'],['downloads','Download','下载管理'],['sources','Blocks','音源管理']]
watch(theme,v=>document.documentElement.dataset.theme=v,{immediate:true});watch(()=>activeAppearance.value?.accent??music.settings.accent,v=>document.documentElement.style.setProperty('--accent',v),{immediate:true});watch(()=>music.settings.animation,v=>document.documentElement.classList.toggle('no-motion',!v),{immediate:true});watch(()=>activeAppearance.value?.font??music.settings.font,v=>{document.documentElement.style.fontFamily=v||''},{immediate:true})
const conversionVersion = ref(0)
watch(() => music.preferences.lyricScript, async script => { await ensureLyricConversion(script); conversionVersion.value++ })
const desktopText = computed(() => { void conversionVersion.value; return convertLyric(desktopStatus.value?.lyricLineAllText || desktopStatus.value?.lyricLineText || desktopStatus.value?.name || '琛瑾音乐 · 等待播放', music.preferences.lyricScript) })
watch([theme,()=>activeAppearance.value?.accent??music.settings.accent,()=>activeAppearance.value?.colors??music.settings.themeColors,()=>componentAppearance.value.global.accentColor], ([mode,accent,colors,customAccent]) => {
  applyMaterialRoles(typeof customAccent==='string'&&/^#[0-9a-f]{6}$/i.test(customAccent)?customAccent:accent,mode==='dark',(colors||{}) as Record<string,string>)
}, { deep: true, immediate: true })
let request=0,suggestTimer:ReturnType<typeof setTimeout>|undefined;const unsubscribers:(()=>void)[]=[]
async function discover(){if(!bridge)return;busy.value=true;const ticket=++request;await music.task(async()=>{if(discoveryTab.value==='playlists'){const data=await invoke<OnlinePlaylist[]>('discovery.playlists',{source:source.value,page:pageNumber.value,tag:''});if(ticket===request)online.value=data}else{const data=await invoke<{id:string;name:string}[]>('discovery.boards',{source:source.value});if(ticket===request){boards.value=data;if(data[0])await loadBoard(data[0].id)}}});if(ticket===request)busy.value=false}
async function loadBoard(id:string){boardId.value=id;busy.value=true;await music.task(async()=>searchResult.value=await invoke<SearchResult>('discovery.board',{source:source.value,id,page:pageNumber.value}));busy.value=false}
async function search(term=keyword.value,newSearch=true){if(!term.trim())return;keyword.value=term;page.value='search';searchFocused.value=false;filter.value='';if(music.settings.searchHistory)music.library.searchHistory=[term,...music.library.searchHistory.filter(value=>value!==term)].slice(0,20)}
watch(keyword,term=>{clearTimeout(suggestTimer);if(!term||!bridge){suggestions.value=[];return}suggestTimer=setTimeout(()=>void invoke<unknown[]>('search.suggest',{source:source.value,keyword:term}).then(items=>suggestions.value=items.map(i=>typeof i==='string'?i:String((i as {name?:string}).name||''))).catch(()=>{}),250)})
function closeSearch():void{searchFocused.value=false}
function dismissSearchOutside(event:Event):void{if(searchFocused.value&&searchBox.value&&!event.composedPath().includes(searchBox.value))closeSearch()}
async function hotSearch(){if(!bridge||!music.settings.hotSearch||source.value==='all'||source.value==='local'){hot.value=[];return}try{const items=await invoke<unknown[]>('search.hot',{source:source.value});hot.value=items.map(i=>typeof i==='string'?i:String((i as {name?:string}).name||''))}catch{hot.value=[]}}
function navigate(next:string,id?:string){page.value=next;filter.value='';if(id)playlistId.value=id;if(next==='discovery'&&(source.value==='all'||source.value==='local'))source.value='wy'}
async function openOnline(item:OnlinePlaylist){busy.value=true;page.value='online';onlineDetail.value=undefined;await music.task(async()=>onlineDetail.value=await invoke('discovery.playlist',{source:item.source,id:item.id}));busy.value=false}
async function importFiles(){await music.task(async()=>{const tracks=await invoke<Track[]>('files.import',{playlistId:playlistId.value});music.notify(`已导入 ${tracks.length} 首歌曲`)})}
async function playlistCall(method:string,params:unknown){await music.task(async()=>{await invoke(method,params);if(bridge){const state=await invoke<import('../../shared/types').LibraryState>('library.load');music.library=state}})}
async function trackAction(action:string,tracks:Track[]){if(!tracks.length)return;
if(action==='alternatives'){alternativesTrack.value=tracks[0];return}
if(action==='copy'||action==='move'){pendingTracks.value=tracks;transferMove.value=action==='move';dialog.value='transfer';return}
if(action==='details'){detailTrack.value=tracks[0];detailLoading.value=true;await music.task(async()=>detailTrack.value=await invoke<Track>('metadata.detail',{track:tracks[0]}));detailLoading.value=false;return}
if(action==='album'||action==='singer'){
  let track=tracks[0],target=trackMetadataTarget(track,action)
  if(!target){const resolved=await music.task(()=>invoke<Track>('metadata.detail',{track}));if(resolved){track=resolved;target=trackMetadataTarget(track,action)}}
  if(!target){music.notify('当前歌曲没有可用的平台资料编号');return}
  onlineTarget.value=target;detailTrack.value=undefined;page.value='metadata';return
}
if(action==='dislike'){music.library.dislikes=[...new Set([...music.library.dislikes,...tracks.map(dislikeRule)])];music.notify('已加入不喜欢，将在播放时跳过');if(music.current&&tracks.some(track=>trackKey(track)===trackKey(music.current!)))void music.next()}if(action==='love')await playlistCall('playlists.add',{playlistId:'love',tracks});if(action==='unlove')await playlistCall('playlists.removeTracks',{playlistId:'love',trackIds:tracks.map(track=>track.id)});if(action==='collectCustom'){pendingTracks.value=tracks;playerCollectOnly.value=true;dialog.value='collect'}if(action==='collect'){pendingTracks.value=tracks;playerCollectOnly.value=false;dialog.value='collect'}if(action==='remove')await playlistCall('playlists.removeTracks',{playlistId:playlistId.value,trackIds:tracks.map(t=>t.id)});if(action==='download')await music.task(async()=>{await invoke('downloads.add',{tracks,quality:music.settings.quality,playlistId:page.value==='playlist'?playlistId.value:undefined});music.notify('已加入下载队列')});if(action==='comments'){commentTrack.value=tracks[0]}if((action==='up'||action==='down')&&playlist.value){const index=playlist.value.tracks.findIndex(track=>trackKey(track)===trackKey(tracks[0])),target=playlist.value.tracks[index+(action==='up'?-1:1)];if(target)await reorderPlaylist(tracks[0],target)}}
async function choosePlaylist(targetId:string):Promise<void>{
 const transfer=dialog.value==='transfer'
 await playlistCall(transfer?'playlists.transfer':'playlists.add',transfer?{from:playlistId.value,to:targetId,trackIds:pendingTracks.value.map(track=>track.id),move:transferMove.value}:{playlistId:targetId,tracks:pendingTracks.value})
 dialog.value=''
}
function addCurrentToPlaylist():void{if(!music.current)return;pendingTracks.value=[music.current];playerCollectOnly.value=true;dialog.value='collect'}
 function createPlaylistForCurrent():void{dialogName.value='';dialog.value='create';void nextTick(()=>dialogInput.value?.focus())}
 async function orderPlaylists(from:number,to:number):Promise<void>{
 const ids=music.library.playlists.map(list=>list.id)
 if(from<0||to<0||from>=ids.length||to>=ids.length||from===to)return
 const [id]=ids.splice(from,1);ids.splice(to,0,id)
 await playlistCall('playlists.order',{ids})
 playlistDrag.value=-1
}
async function refreshLinked():Promise<void>{await playlistCall('playlist.refresh',{playlistId:playlistId.value})}
async function reorderPlaylist(from:Track,to:Track){if(!playlist.value)return;const ids=playlist.value.tracks.map(track=>track.id),start=ids.indexOf(from.id),end=ids.indexOf(to.id);if(start<0||end<0)return;const [id]=ids.splice(start,1);ids.splice(end,0,id);await playlistCall('playlists.reorder',{playlistId:playlistId.value,trackIds:ids})}
async function loadComments(){await music.task(async()=>comments.value=await invoke<Comment[]>('comments',{track:commentTrack.value,page:commentPage.value}))}
function openDialog(mode:'create'|'rename'|'remove'){playerCollectOnly.value=false;dialog.value=mode;dialogName.value=mode==='rename'?playlist.value?.name||'':'';void nextTick(()=>dialogInput.value?.focus())}
async function submitDialog(){
 if(dialog.value==='create'&&dialogName.value.trim()){
  const addCurrent=playerCollectOnly.value,existing=new Set(music.library.playlists.map(list=>list.id))
  await playlistCall('playlists.create',{name:dialogName.value.trim()})
  const created=music.library.playlists.find(list=>!existing.has(list.id))
  if(addCurrent&&created&&pendingTracks.value.length)await playlistCall('playlists.add',{playlistId:created.id,tracks:pendingTracks.value})
  if(created)navigate('playlist',created.id)
 }else if(dialog.value==='rename'&&dialogName.value.trim())await playlistCall('playlists.rename',{id:playlistId.value,name:dialogName.value.trim()})
 else if(dialog.value==='remove'){await playlistCall('playlists.remove',{id:playlistId.value});navigate('home')}
 else return
 dialog.value=''
}
async function backup(method:string){await music.task(async()=>{const result=await invoke<string|null>(`backup.${method}`,{playlistId:page.value==='playlist'?playlistId.value:undefined});if(result===null)return;if(method==='exportText'){const url=URL.createObjectURL(new Blob([result||''],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`琛瑾音乐-${page.value==='playlist'?playlist.value?.name:'资料库'}-${new Date().toISOString().slice(0,10)}.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}music.notify(method==='import'?'备份已导入':'已导出到所选位置')})}
function keyboard(event: KeyboardEvent): void {
  if (event.key === 'Tab') {
    const modal = document.querySelector<HTMLElement>('[role="dialog"]')
    if (modal) {
      const items = [...modal.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,[tabindex="0"]')]
      const first = items[0], last = items.at(-1)
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus() }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
    }
  }
  if (event.key === 'Escape') { closeSearch(); if(dialog.value)dialog.value='';else if(commentTrack.value)commentTrack.value=undefined;else if(drawer.value)drawer.value=false;else fullLyrics.value=false }
  const target = event.target as HTMLElement
  if (['INPUT', 'TEXTAREA', 'SELECT'].includes(target.tagName) || target.isContentEditable || event.repeat) return
  const actions: Record<string, () => void> = {
    toggle: () => void music.toggle(), next: () => void music.next(), previous: () => void music.previous(),
    search: () => document.querySelector<HTMLInputElement>('.search-input')?.focus(),
    volumeUp: () => void music.updateSettings({ volume: Math.min(1, music.settings.volume + 0.05) }),
    volumeDown: () => void music.updateSettings({ volume: Math.max(0, music.settings.volume - 0.05) }),
    mute: () => void music.updateSettings({ muted: !music.settings.muted }),
    seekBack:()=>music.service.seek(Math.max(0,music.progress-5)),seekForward:()=>music.service.seek(music.progress+5),
    collect:()=>{if(music.current)void trackAction('love',[music.current])},uncollect:()=>{if(music.current)void playlistCall('playlists.removeTracks',{playlistId:'love',trackIds:[music.current.id]})},dislike:()=>{if(music.current)void trackAction('dislike',[music.current])},
    desktopLyric:()=>{const enabled=!music.settings.desktopLyric;void music.task(()=>invoke('desktop.lyric',{enabled}))},desktopLock:()=>void music.task(()=>invoke('desktop.lock',{enabled:!music.settings.desktopLyricLock})),desktopTop:()=>void music.task(()=>invoke('desktop.top',{enabled:music.settings.desktopLyricTop===false})),
    windowMinimize:()=>void music.task(()=>invoke('window.command',{action:'min'})),windowToggleMin:()=>void music.task(()=>invoke('window.command',{action:'toggleMin'})),windowToggleHide:()=>void music.task(()=>invoke('window.command',{action:'toggleHide'})),windowClose:()=>void music.task(()=>invoke('window.command',{action:'close'})),
    lyrics: () => { fullLyrics.value = !fullLyrics.value }, queue: () => { drawer.value = !drawer.value },
  }
  for (const [action, shortcut] of Object.entries(music.preferences.shortcuts)) {
    if (shortcutMatches(event, shortcut) && actions[action]) { event.preventDefault(); actions[action](); break }
  }
}
onMounted(async()=>{interfaceTranslation=installInterfaceTranslation(document.getElementById('app')!);await interfaceTranslation.setLanguage(music.settings.language);if(desktopMode)return;document.addEventListener('keydown',keyboard);document.addEventListener('pointerdown',dismissSearchOutside,true);document.addEventListener('focusin',dismissSearchOutside);window.addEventListener('blur',closeSearch);unsubscribers.push(bridge?.on('app.deeplink',(data:{action:string;track?:Track;tracks?:Track[];index?:number;source?:SourceId|'all';id?:string;keyword?:string})=>{if(data.action==='priorityLater'&&data.tracks?.length)music.later(data.tracks);if(data.action==='priorityPlay'&&data.tracks?.length){music.playNext(data.tracks);void music.next()}if(data.action==='openOnline'&&data.source&&data.id){source.value=data.source;onlineImportTarget.value=data.id;page.value='discovery'}if(data.action==='playList'&&data.tracks?.length)void music.play(data.tracks[data.index||0]||data.tracks[0],data.tracks);if(data.action==='play'&&data.track)void music.play(data.track);if(data.action==='search'&&data.keyword){source.value=data.source||'all';void search(data.keyword)}})||(()=>{}));unsubscribers.push(bridge?.on('app.error',(data:{message:string})=>music.error=data.message)||(()=>{}));await music.refresh();void hotSearch()});onUnmounted(()=>{systemAppearance.removeEventListener('change',systemAppearanceChanged);interfaceTranslation?.dispose();document.removeEventListener('keydown',keyboard);document.removeEventListener('pointerdown',dismissSearchOutside,true);document.removeEventListener('focusin',dismissSearchOutside);window.removeEventListener('blur',closeSearch);unsubscribers.forEach(fn=>fn());clearTimeout(suggestTimer)})
