<template>
 <DesktopLyrics v-if="desktopMode"/>
 <div v-else class="app-shell" :class="{'lyrics-open':fullLyrics}" :style="shellScale">
   <div v-if="backgroundStyle" class="theme-image-background" :style="backgroundStyle" aria-hidden="true"/>
  <aside class="sidebar"><a href="#" class="brand" aria-label="琛瑾音乐首页" @click.prevent="navigate('home')"><div class="brand-mark"><Icon name="AudioLines" :size="26"/></div><span>琛瑾<span class="brand-light">音乐</span><small>CHENJIN MUSIC</small></span></a><div class="nav-label">在线音乐</div><nav aria-label="主导航"><button v-for="item in navigation" :key="item[0]" class="nav-item" :class="{active:page===item[0]}" :aria-current="page===item[0]?'page':undefined" @click="navigate(item[0])"><Icon :name="item[1]" :size="19"/><span>{{item[2]}}</span><span v-if="item[0]==='downloads'&&music.library.downloads.some(t=>t.status==='running')" class="nav-dot"/></button></nav><div class="nav-label playlist-label"><span>我的歌单</span><button class="icon-button" aria-label="新建歌单" @click="openDialog('create')"><Icon name="Plus" :size="16"/></button></div><nav class="playlist-nav" aria-label="我的歌单"><button v-for="(list,listIndex) in music.library.playlists" :key="list.id" class="nav-item" draggable="true" @dragstart="playlistDrag=listIndex;$event.dataTransfer?.setData('text/plain',list.id)" @dragover.prevent @drop.prevent="orderPlaylists(playlistDrag,listIndex)" @dragend="playlistDrag=-1" @keydown.alt.up.prevent="orderPlaylists(listIndex,listIndex-1)" @keydown.alt.down.prevent="orderPlaylists(listIndex,listIndex+1)" :class="{active:page==='playlist'&&playlistId===list.id}" :aria-current="page==='playlist'&&playlistId===list.id?'page':undefined" @click="navigate('playlist',list.id)"><Icon :name="list.id==='love'?'Heart':list.id==='default'?'Library':'ListMusic'" :size="18"/><span class="text-ellipsis" data-i18n-ignore>{{list.name}}</span><small>{{list.tracks.length||''}}</small></button></nav><div class="sidebar-bottom"><div class="library-stat"><span class="status-dot"/><span>{{bridge?'你的音乐，自在收藏':'浏览器预览 · 未连接桌面'}}</span></div><button class="nav-item" :class="{active:page==='settings'}" :aria-current="page==='settings'?'page':undefined" @click="navigate('settings')"><Icon name="Settings2" :size="19"/>设置</button></div></aside>
  <div class="workspace"><header class="topbar"><div class="topbar-left"><button class="icon-button" aria-label="返回首页" @click="navigate('home')"><Icon name="ChevronLeft"/></button><span class="topbar-caption">为每一次聆听而设计</span></div><form ref="searchBox" class="search-box" role="search" @submit.prevent="search()"><Icon name="Search" :size="18"/><input v-model="keyword" class="search-input" placeholder="搜索歌曲、艺人、专辑" aria-label="搜索音乐" :aria-expanded="searchFocused" aria-controls="search-suggestions" @focus="searchFocused=true;hotSearch()" @click="searchFocused=true" @keydown.esc="searchFocused=false"/><kbd>Ctrl F</kbd><div v-if="searchFocused" id="search-suggestions" class="search-popover"><div class="section-title search-popover-header"><strong>{{keyword?'搜索建议':'最近搜索'}}</strong><div class="search-popover-actions"><button v-if="!keyword" class="search-clear" type="button" @click="music.library.searchHistory=[]">清空</button><button class="icon-button" type="button" aria-label="关闭搜索建议" @click="searchFocused=false"><Icon name="X" :size="16"/></button></div></div><button v-for="term in keyword?suggestions:music.library.searchHistory.slice(0,6)" :key="term" type="button" class="suggestion" :title="term" @click="search(term)"><Icon name="Search" :size="14"/><span class="suggestion-text" data-i18n-ignore>{{term}}</span></button><p v-if="keyword&&!suggestions.length" class="muted">按 Enter 搜索「{{keyword}}」</p><template v-if="!keyword&&hot.length"><strong class="hot-label">平台热门搜索</strong><div class="chips"><button v-for="term in hot.slice(0,8)" :key="term" type="button" @click="search(term)">{{term}}</button></div></template><p v-if="!keyword&&!hot.length&&!music.library.searchHistory.length" class="muted">从一个喜欢的名字开始。</p></div></form><Teleport to="body" :disabled="!fullLyrics"><div class="window-actions" :class="{'lyrics-window-actions':fullLyrics}"><button class="theme-toggle icon-button" aria-label="切换明暗主题" @click="music.updateSettings({theme:theme==='dark'?'light':'dark'})"><Icon :name="theme==='dark'?'Sun':'Moon'" :size="18"/></button><template v-if="bridge"><button class="icon-button" aria-label="最小化窗口" @click="bridge.window('minimize')"><Icon name="Minus" :size="17"/></button><button class="icon-button" aria-label="最大化窗口" @click="bridge.window('maximize')"><Icon name="Square" :size="14"/></button><button class="icon-button close-window" aria-label="关闭窗口" @click="bridge.window('close')"><Icon name="X" :size="18"/></button></template></div></Teleport></header>
  <main class="main-content" :data-page="page" :class="{'lyrics-open':fullLyrics}">
   <Transition name="page" mode="out-in"><div :key="`${page}:${page==='playlist'?playlistId:''}`" class="page-view" :data-page="page"><div v-if="!bridge"><Icon name="Monitor" :size="17"/><span>你正在浏览界面预览。打开桌面客户端即可导入歌曲、连接音源与播放。</span></div>
   <div v-if="music.error" class="error-banner" role="alert"><Icon name="CircleAlert" :size="18"/><span>{{music.error}}</span><button class="icon-button" aria-label="关闭错误提示" @click="music.error=''"><Icon name="X" :size="16"/></button></div>
   <div v-if="music.loading" class="empty-state"><span class="spinner"/>正在读取你的音乐库…</div>
   <template v-else-if="page==='home'"><div class="page-heading home-heading"><div><p class="eyebrow">YOUR DAILY SOUNDTRACK</p><h1>好时光，值得好音乐<span class="accent">。</span></h1><p>在熟悉的旋律里，发现新的自己。</p></div><span class="date-label">{{new Date().toLocaleDateString(normalizeInterfaceLanguage(music.settings.language),{month:'long',day:'numeric',weekday:'long'})}}</span></div>
    <section class="welcome-hero"><div class="hero-content"><span class="hero-badge"><span/>属于你的音乐空间</span><h2>把世界调成<br/>你喜欢的频率。</h2><p>{{allTracks.length?`你已收藏 ${allTracks.length} 首歌曲。熟悉的声音，随时为你响起。`:'从第一首喜欢的歌开始，让每段日常都有自己的背景音乐。'}}</p><div class="button-row"><button class="primary-button" @click="allTracks.length?music.play(allTracks[0],allTracks):importFiles()"><Icon :name="allTracks.length?'Play':'FolderPlus'" :size="18"/>{{allTracks.length?'播放我的音乐':'导入本地音乐'}}</button><button class="hero-secondary" @click="navigate('discovery')">探索新声音<Icon name="ArrowUpRight" :size="17"/></button></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"/><div class="orbit orbit-two"/><div class="record"><div class="record-label"><Icon name="AudioLines" :size="46"/><span>CHENJIN</span></div></div><div class="floating-note note-one"><Icon name="Music2" :size="24"/></div><div class="floating-note note-two"><Icon name="Sparkles" :size="20"/></div><span class="art-caption">JUST YOU & THE MUSIC</span></div></section>
    <section class="home-section"><div class="section-title"><div><h2>我的音乐角落 <span class="count-pill">{{music.library.playlists.length}}</span></h2><p>收藏每一种心情。</p></div><button class="text-button" @click="openDialog('create')"><Icon name="Plus" :size="16"/>创建歌单</button></div><div class="playlist-cards"><button v-for="(list,i) in music.library.playlists" :key="list.id" class="playlist-card" @click="navigate('playlist',list.id)"><div class="playlist-art" :class="`art-${i%4}`"><img v-if="list.tracks.find(t=>t.meta.picUrl)?.meta.picUrl" :src="list.tracks.find(t=>t.meta.picUrl)?.meta.picUrl||''" alt=""/><template v-else><Icon :name="list.id==='love'?'Heart':list.id==='default'?'Headphones':'ListMusic'" :size="42"/><span>{{list.id==='love'?'WITH LOVE':'MY COLLECTION'}}</span></template><span class="card-play"><Icon name="Play" :size="22"/></span></div><strong data-i18n-ignore>{{list.name}}</strong><small>{{list.tracks.length}} 首 · {{list.id==='love'?'心动的声音':'私人收藏'}}</small></button><button class="playlist-card new-playlist-card" @click="openDialog('create')"><div class="playlist-art"><Icon name="Plus" :size="34"/><span>NEW PLAYLIST</span></div><strong>为心情建一张歌单</strong><small>把喜欢留在这里</small></button></div></section>
    <section class="home-section"><div class="section-title"><div><h2>继续聆听</h2><p>让旋律接着流动。</p></div><button v-if="music.queue.length" class="text-button" @click="drawer=true">查看队列<Icon name="ArrowRight" :size="16"/></button></div><TrackList v-if="music.queue.length" :tracks="music.queue.slice(0,5)" @action="trackAction"/><div v-else class="quiet-empty"><div class="empty-icon"><Icon name="Disc3" :size="27"/></div><div><h3>你的下一首好歌，还在路上</h3><p>导入音乐或接入音源，即可开始你的聆听旅程。</p></div><button class="text-button" @click="navigate('sources')">管理音源<Icon name="ArrowRight" :size="16"/></button></div></section>
   </template>
   <OnlinePanel v-else-if="page==='discovery'||page==='search'||page==='metadata'" :view="page as 'discovery'|'search'|'metadata'" :source="source" :keyword="keyword" :target="onlineTarget" :import-address="onlineImportTarget" @source="source=$event" @action="trackAction" @back="navigate('home')"/>
   <template v-else-if="page==='playlist'"><div v-if="page==='playlist'" class="playlist-heading"><div class="playlist-heading-art"><img v-if="playlist?.tracks.find(t=>t.meta.picUrl)?.meta.picUrl" :src="playlist.tracks.find(t=>t.meta.picUrl)?.meta.picUrl||''" alt=""/><Icon v-else :name="playlistId==='love'?'Heart':'ListMusic'" :size="52"/></div><div><p class="eyebrow">PERSONAL COLLECTION</p><h1 data-i18n-ignore>{{playlist?.name}}</h1><p>{{playlist?.tracks.length||0}} 首歌曲 · 创建于 {{new Date(playlist?.createdAt||Date.now()).toLocaleDateString()}}</p><div class="button-row"><button class="primary-button" :disabled="!filteredTracks.length" @click="music.play(filteredTracks[0],filteredTracks)"><Icon name="Play" :size="16"/>播放全部</button><button @click="importFiles"><Icon name="FolderPlus" :size="16"/>导入音乐</button><button v-if="playlist?.sourceListId" @click="refreshLinked"><Icon name="RefreshCw" :size="16"/>更新在线歌单</button><button class="icon-button" aria-label="向上移动歌单" @click="orderPlaylists(music.library.playlists.findIndex(list=>list.id===playlistId),music.library.playlists.findIndex(list=>list.id===playlistId)-1)"><Icon name="ChevronUp" :size="16"/></button><button class="icon-button" aria-label="向下移动歌单" @click="orderPlaylists(music.library.playlists.findIndex(list=>list.id===playlistId),music.library.playlists.findIndex(list=>list.id===playlistId)+1)"><Icon name="ChevronDown" :size="16"/></button><button v-if="!['default','love'].includes(playlistId)" @click="openDialog('rename')" aria-label="重命名歌单"><Icon name="Pencil" :size="16"/></button></div></div></div>
    <div class="list-toolbar"><strong>歌曲列表 <span class="muted">{{filteredTracks.length}}</span></strong><div class="button-row"><label class="filter-input"><Icon name="Search" :size="14"/><input v-model="filter" placeholder="筛选当前列表" aria-label="筛选当前列表"/></label><template v-if="page==='playlist'"><select v-model="sortField" :aria-label="interfaceText('歌曲排序字段')"><option v-for="(label,key) in {name:'歌名',singer:'艺人',albumName:'专辑',interval:'时长',source:'来源',random:'随机排序'}" :key="key" :value="key">{{interfaceText(label)}}</option></select><select v-model="sortDirection" :disabled="sortField==='random'" :aria-label="interfaceText('歌曲排序方向')"><option value="asc">{{interfaceText('升序')}}</option><option value="desc">{{interfaceText('降序')}}</option></select><button @click="playlistCall('playlists.sort',{playlistId,field:sortField,direction:sortDirection})">排序歌单</button><button @click="playlistCall('playlists.dedupe',{playlistId})" title="根据来源与歌曲 ID 去重"><Icon name="ListFilter" :size="15"/>去重</button><button @click="backup('export')">导出</button><button @click="backup('exportText')">文本</button><button v-if="!['default','love'].includes(playlistId)" class="icon-button" aria-label="删除歌单" @click="openDialog('remove')"><Icon name="Trash2" :size="16"/></button></template></div></div><TrackList :tracks="filteredTracks" :editable="page==='playlist'" :loading="busy" @action="trackAction" @reorder="reorderPlaylist"/></template>
   <template v-else-if="page==='sources'"><div class="page-heading"><div><p class="eyebrow">OPEN UP YOUR MUSIC</p><h1>音源管理</h1><p>导入你信任的音源脚本，连接更多声音。</p></div><button class="primary-button" @click="music.task(async()=>{const result=await invoke('sources.import');if(result)music.notify('音源脚本已导入')})"><Icon name="Plus" :size="17"/>导入音源</button></div><div class="info-card"><Icon name="ShieldCheck" :size="24"/><div><strong>音乐来自你选择的音源</strong><p>脚本提供播放地址与音质能力。仅导入你信任的脚本；平台歌曲资料不代表地址一定可播放。</p></div><span class="count-pill">{{activeScripts.length}} 个已启用</span></div><form class="source-url-form" @submit.prevent="importSourceURL"><label for="source-url">从链接导入音源脚本</label><div class="button-row"><input id="source-url" v-model="sourceURL" type="url" maxlength="2048" placeholder="https://…/source.js" required/><button :disabled="!bridge||!sourceURL.trim()" type="submit">导入链接</button></div></form><div v-if="!music.library.scripts.length" class="empty-state"><div class="empty-icon"><Icon name="Blocks" :size="35"/></div><h3>为音乐打开一扇门</h3><p>导入兼容音源脚本，或直接导入本地文件开始播放。</p><button @click="importFiles">导入本地音乐</button></div><article v-for="script in music.library.scripts" :key="script.id" class="source-card"><div class="source-logo"><Icon name="Radio" :size="28"/></div><div class="source-info"><h3>{{script.name}} <span class="count-pill">{{script.version}}</span></h3><p>{{script.description||'暂无描述'}}</p><small>{{script.author||'未知作者'}} · {{script.status}}</small><div class="chips"><span v-for="(config,key) in script.sources" :key="key">{{sourceNames[key as SourceId]||key}} · {{config.qualitys.join(' / ')}}</span></div><details v-if="script.updateLog" class="source-update-notes"><summary>{{interfaceText('更新说明')}}</summary><pre data-i18n-ignore>{{script.updateLog}}</pre></details></div><div class="button-row"><button v-if="externalLink(script.updateURL)" @click="openExternal(script.updateURL!)">{{interfaceText('查看音源更新')}}</button><button v-if="externalLink(script.homepage)" @click="openExternal(script.homepage!)">{{interfaceText('作者主页')}}</button><button :class="{active:script.enabled}" @click="music.task(()=>invoke('sources.activate',{id:script.id,enabled:!script.enabled}))">{{script.enabled?'停用':'启用'}}</button><button class="icon-button" :aria-label="`移除 ${script.name}`" @click="music.task(()=>invoke('sources.remove',{id:script.id}))"><Icon name="Trash2" :size="17"/></button></div></article><div class="section-title backup-title"><div><h2>资料库备份</h2><p>保存歌单、偏好与音源配置。</p></div><div class="button-row"><button @click="backup('import')"><Icon name="Upload" :size="16"/>导入备份</button><button @click="backup('export')"><Icon name="Download" :size="16"/>导出备份</button></div></div></template>
   <DownloadsPanel v-else-if="page==='downloads'"/>
   <SettingsPanel v-else-if="page==='settings'"/>
  </div></Transition></main></div>
  <PlayerBar @queue="drawer=!drawer" @lyrics="fullLyrics=!fullLyrics" @add-playlist="addCurrentToPlaylist"/>
  <Transition name="fade"><QueueDrawer v-if="drawer" @close="drawer=false"/></Transition>
  <Transition name="lyrics"><LyricsView v-if="fullLyrics" @close="fullLyrics=false"/></Transition>
  <div v-if="dialog" class="modal-backdrop" @click.self="dialog='';playerCollectOnly=false"><section class="modal" role="dialog" aria-modal="true" :aria-label="dialog==='collect'?'添加到歌单':dialog==='transfer'?(transferMove?'移动到歌单':'复制到歌单'):'管理歌单'" @keydown.esc="dialog='';playerCollectOnly=false"><div class="section-title"><h2>{{{create:'创建新歌单',rename:'重命名歌单',remove:'删除歌单',collect:'添加到歌单',transfer:transferMove?'移动到歌单':'复制到歌单'}[dialog]}}</h2><button class="icon-button" aria-label="关闭弹窗" @click="dialog='';playerCollectOnly=false"><Icon name="X"/></button></div><template v-if="dialog==='collect'||dialog==='transfer'"><p class="muted">为 {{pendingTracks.length}} 首歌曲选择一个归属。</p><div v-if="dialog==='collect'&&playerCollectOnly&&!customPlaylists.length" class="empty-state collect-empty"><Icon name="ListMusic" :size="25"/><h3>还没有自定义歌单</h3><button class="primary-button" @click="createPlaylistForCurrent"><Icon name="Plus" :size="15"/>新建歌单</button></div><button v-for="list in playerCollectOnly?customPlaylists:music.library.playlists.filter(item=>dialog!=='transfer'||item.id!==playlistId)" :key="list.id" class="collect-choice" @click="choosePlaylist(list.id)"><Icon name="ListMusic" :size="18"/><span data-i18n-ignore>{{list.name}}</span><small>{{list.tracks.length}} 首</small></button></template><form v-else @submit.prevent="submitDialog"><p v-if="dialog==='remove'">确定删除「{{playlist?.name}}」？本地音乐文件会保留。</p><label v-else class="modal-field">歌单名称<input ref="dialogInput" v-model="dialogName" maxlength="100" placeholder="给这份心情取个名字" required/></label><div class="modal-actions"><button type="button" @click="dialog='';playerCollectOnly=false">取消</button><button type="submit" :class="dialog==='remove'?'danger-button':'primary-button'">{{dialog==='remove'?'删除':'保存'}}</button></div></form></section></div>
  <SourceAlternatives v-if="alternativesTrack" :track="alternativesTrack" @close="alternativesTrack=undefined"/>
  <TrackDetails v-if="detailTrack" :track="detailTrack" :loading="detailLoading" @close="detailTrack=undefined" @action="trackAction"/>
  <CommentsPanel v-if="commentTrack" :track="commentTrack" @close="commentTrack=undefined"/>
  <Transition name="fade"><div v-if="music.notice" class="toast" role="status"><Icon name="CheckCircle2" :size="18"/>{{music.notice}}</div></Transition>
 </div>
</template>
<style scoped>.source-update-notes{font-size:11px;color:var(--muted);margin-top:12px}.source-update-notes pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:11px;line-height:1.7;max-height:180px;overflow:auto;margin-top:10px}</style>
